DROP TRIGGER IF EXISTS actualizar_orden;

DELIMITER //

CREATE TRIGGER actualizar_orden
BEFORE INSERT ON etapas
FOR EACH ROW 
BEGIN
    DECLARE valor INT;
    SELECT COUNT(id) INTO valor FROM etapas WHERE id_puesto = NEW.id_puesto;
    SET valor = valor + 1;

    SET NEW.orden = valor;
END //